def splitListToParts(head, k):
    # Count length
    n, curr = 0, head
    while curr:
        n += 1
        curr = curr.next
    base, extra = divmod(n, k)
    result = []
    curr = head
    for i in range(k):
        part_head = curr
        size = base + (1 if i < extra else 0)
        for _ in range(size - 1):
            if curr:
                curr = curr.next
        if curr:
            curr.next, curr = None, curr.next
        result.append(part_head)
    return result

