def flatten(root):
    curr = root
    while curr:
        if curr.left:
            # Find rightmost of left subtree
            rightmost = curr.left
            while rightmost.right:
                rightmost = rightmost.right
            # Connect
            rightmost.right = curr.right
            curr.right = curr.left
            curr.left = None
        curr = curr.right

def build_flat_tree(vals):
    if not vals: return None
    root = TreeNodeFlat(vals[0])
    q = [root]; i = 1
    while q and i < len(vals):
        node = q.pop(0)
        if i < len(vals) and vals[i] is not None:
            node.left = TreeNodeFlat(vals[i]); q.append(node.left)
        i += 1
        if i < len(vals) and vals[i] is not None:
            node.right = TreeNodeFlat(vals[i]); q.append(node.right)
        i += 1
    return root

