def isSubPath(head, root):
    def matches(list_node, tree_node):
        if not list_node:
            return True
        if not tree_node:
            return False
        if list_node.val != tree_node.val:
            return False
        return matches(list_node.next, tree_node.left) or matches(list_node.next, tree_node.right)

    if not root:
        return False
    if matches(head, root):
        return True
    return isSubPath(head, root.left) or isSubPath(head, root.right)

