class AllOne:
    class Bucket:
        def __init__(self, count):
            self.count = count
            self.keys = set()
            self.prev = self.next = None

    def __init__(self):
        self.head = self.Bucket(0)  # dummy min
        self.tail = self.Bucket(float('inf'))  # dummy max
        self.head.next = self.tail
        self.tail.prev = self.head
        self.key_bucket = {}  # key -> bucket

    def _insert_after(self, bucket, count):
        new = self.Bucket(count)
        new.next = bucket.next
        new.prev = bucket
        bucket.next.prev = new
        bucket.next = new
        return new

    def _remove_bucket(self, bucket):
        bucket.prev.next = bucket.next
        bucket.next.prev = bucket.prev

    def inc(self, key):
        if key not in self.key_bucket:
            bucket = self.head
        else:
            bucket = self.key_bucket[key]
            bucket.keys.discard(key)

        if bucket.next.count != bucket.count + 1:
            self._insert_after(bucket, bucket.count + 1)
        bucket.next.keys.add(key)
        self.key_bucket[key] = bucket.next

        if not bucket.keys and bucket != self.head:
            self._remove_bucket(bucket)

    def dec(self, key):
        bucket = self.key_bucket[key]
        bucket.keys.discard(key)

        if bucket.count - 1 == 0:
            del self.key_bucket[key]
        else:
            if bucket.prev.count != bucket.count - 1:
                self._insert_after(bucket.prev, bucket.count - 1)
            bucket.prev.keys.add(key)
            self.key_bucket[key] = bucket.prev

        if not bucket.keys:
            self._remove_bucket(bucket)

    def getMaxKey(self):
        if self.tail.prev == self.head:
            return ""
        return next(iter(self.tail.prev.keys))

    def getMinKey(self):
        if self.head.next == self.tail:
            return ""
        return next(iter(self.head.next.keys))

