def sortListBottomUp(head):
    if not head or not head.next:
        return head

    # Find length
    n = 0
    curr = head
    while curr:
        n += 1
        curr = curr.next

    def split(node, size):
        """Cut a sublist of given size and return the rest."""
        for _ in range(size - 1):
            if not node:
                break
            node = node.next
        if not node:
            return None
        rest = node.next
        node.next = None
        return rest

    def merge_two(l1, l2):
        dummy = ListNode(0)
        curr = dummy
        while l1 and l2:
            if l1.val <= l2.val:
                curr.next = l1; l1 = l1.next
            else:
                curr.next = l2; l2 = l2.next
            curr = curr.next
        curr.next = l1 or l2
        return dummy.next, curr if not (l1 or l2) else (dummy.next, None)

    dummy = ListNode(0, head)
    size = 1
    while size < n:
        curr = dummy.next
        tail = dummy
        while curr:
            left = curr
            right = split(left, size)
            curr = split(right, size)
            # merge left and right
            prev_tail, _ = None, None
            p1, p2 = left, right
            tmp = ListNode(0)
            t = tmp
            while p1 and p2:
                if p1.val <= p2.val:
                    t.next = p1; p1 = p1.next
                else:
                    t.next = p2; p2 = p2.next
                t = t.next
            t.next = p1 or p2
            while t.next:
                t = t.next
            tail.next = tmp.next
            tail = t
        size *= 2
    return dummy.next

class BrowserHistory:
    class Page:
        def __init__(self, url):
            self.url = url
            self.prev = self.next = None

    def __init__(self, homepage):
        self.curr = self.Page(homepage)

    def visit(self, url):
        new = self.Page(url)
        new.prev = self.curr
        self.curr.next = new
        self.curr = new

    def back(self, steps):
        while steps > 0 and self.curr.prev:
            self.curr = self.curr.prev
            steps -= 1
        return self.curr.url

    def forward(self, steps):
        while steps > 0 and self.curr.next:
            self.curr = self.curr.next
            steps -= 1
        return self.curr.url

