def getIntersectionNode(headA, headB):
    def length(h):
        l = 0
        while h:
            l += 1
            h = h.next
        return l
    la, lb = length(headA), length(headB)
    a, b = headA, headB
    while la > lb:
        a = a.next; la -= 1
    while lb > la:
        b = b.next; lb -= 1
    while a is not b:
        a = a.next; b = b.next
    return a

