    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def insertCircular(head, val):
    new_node = CNode(val)
    if not head:
        new_node.next = new_node
        return new_node
    cur = head
    while True:
        nxt = cur.next
        # Normal insertion point
        if cur.val <= val <= nxt.val:
            break
        # At the max->min boundary
        if cur.val > nxt.val:
            if val >= cur.val or val <= nxt.val:
                break
        if cur.next is head:
            break
        cur = cur.next
    new_node.next = cur.next
    cur.next = new_node
    return head

