def removeNodes(head):
    # Reverse
    prev, cur = None, head
    while cur:
        nxt = cur.next; cur.next = prev; prev = cur; cur = nxt
    # Keep monotone non-decreasing from new head
    new_head = prev
    cur = new_head
    max_val = cur.val
    while cur and cur.next:
        if cur.next.val < max_val:
            cur.next = cur.next.next
        else:
            max_val = cur.next.val
            cur = cur.next
    # Reverse back
    prev, cur = None, new_head
    while cur:
        nxt = cur.next; cur.next = prev; prev = cur; cur = nxt
    return prev

