def reverseKGroupAll(head, k):
    dummy = ListNode(0, head)
    prev_tail = dummy
    cur = head
    while cur:
        group_start = cur
        group_end = cur
        for _ in range(k - 1):
            if group_end.next:
                group_end = group_end.next
            else:
                break
        next_group = group_end.next
        group_end.next = None
        # Reverse this group
        p, c = None, group_start
        while c:
            n = c.next; c.next = p; p = c; c = n
        prev_tail.next = p
        group_start.next = next_group
        prev_tail = group_start
        cur = next_group
    return dummy.next

class GraphNode:
    def __init__(self, val=0, neighbors=None):
        self.val = val
        self.neighbors = neighbors if neighbors else []

def cloneGraph(node):
    if not node:
        return None
    cloned = {}
    from collections import deque
    q = deque([node])
    cloned[node] = GraphNode(node.val)
    while q:
        cur = q.popleft()
        for nb in cur.neighbors:
            if nb not in cloned:
                cloned[nb] = GraphNode(nb.val)
                q.append(nb)
            cloned[cur].neighbors.append(cloned[nb])
    return cloned[node]

