class DNode:
    def __init__(self, val=0):
        self.val = val
        self.prev = self.next = None

class Deque:
    def __init__(self):
        self.head = DNode()  # sentinel
        self.tail = DNode()  # sentinel
        self.head.next = self.tail
        self.tail.prev = self.head
        self.size = 0

    def _insert_after(self, node, val):
        new = DNode(val)
        new.next = node.next
        new.prev = node
        node.next.prev = new
        node.next = new
        self.size += 1

    def _remove(self, node):
        node.prev.next = node.next
        node.next.prev = node.prev
        self.size -= 1
        return node.val

    def appendLeft(self, val):
        self._insert_after(self.head, val)

    def appendRight(self, val):
        self._insert_after(self.tail.prev, val)

    def popLeft(self):
        if self.size == 0:
            raise IndexError('deque is empty')
        return self._remove(self.head.next)

    def popRight(self):
        if self.size == 0:
            raise IndexError('deque is empty')
        return self._remove(self.tail.prev)

    def peekLeft(self):
        return self.head.next.val if self.size > 0 else None

    def peekRight(self):
        return self.tail.prev.val if self.size > 0 else None

    def __len__(self):
        return self.size

