class SkipNode:
    def __init__(self, val, down=None, right=None):
        self.val = val
        self.down = down   # to the same node in level below
        self.right = right # next node at same level

class SkipList:
    def __init__(self):
        NEG_INF = float('-inf')
        self.L0 = SkipNode(NEG_INF)  # level 0 sentinel
        self.L1 = SkipNode(NEG_INF)  # level 1 sentinel
        self.L1.down = self.L0

    def search(self, val):
        cur = self.L1
        while cur:
            if cur.right and cur.right.val <= val:
                cur = cur.right
                if cur.val == val:
                    return True
            elif cur.down:
                cur = cur.down
            else:
                break
        return False

    def add(self, val):
        # Insert into level 0
        cur = self.L0
        while cur.right and cur.right.val < val:
            cur = cur.right
        new_l0 = SkipNode(val, right=cur.right)
        cur.right = new_l0
        # Coin flip for level 1
        if random.random() < 0.5:
            cur1 = self.L1
            while cur1.right and cur1.right.val < val:
                cur1 = cur1.right
            new_l1 = SkipNode(val, down=new_l0, right=cur1.right)
            cur1.right = new_l1

    def erase(self, val):
        found = False
        for head in [self.L1, self.L0]:
            cur = head
            while cur.right and cur.right.val <= val:
                if cur.right.val == val:
                    cur.right = cur.right.right
                    found = True
                    break
                cur = cur.right
        return found

